package com.xksystem.logistics.tom.internal;
import com.xksystem.logistics.tom.*;
import com.xksystem.logistics.tom.closure.*;
import com.xksystem.logistics.tms.*;
import com.xksystem.logistics.tms.execution.ExecutionPhase;
import com.xksystem.logistics.upms.AccountDto;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import tools.jackson.databind.json.JsonMapper;
@Repository
class OrderClosureStore {
 static final String SCOPE="SINGLE_COMPANY";
 record Receipt(String hash,ClosureDtos.Result data){}
 private final JdbcTemplate jdbc;private final JsonMapper json;private final TomOrderRepository orders;private final OrderClosureFacts facts;
 OrderClosureStore(JdbcTemplate jdbc,JsonMapper json,TomOrderRepository orders,OrderClosureFacts facts){this.jdbc=jdbc;this.json=json;this.orders=orders;this.facts=facts;}
 Optional<ClosureDtos.Witness> witness(UUID order){var rows=jdbc.queryForList("SELECT * FROM logistics.tom_order_closure WHERE order_id=? AND company_scope=?",order,SCOPE);return rows.isEmpty()?Optional.empty():Optional.of(witness(rows.getFirst()));}
 private ClosureDtos.Witness witness(Map<String,Object> r){return new ClosureDtos.Witness((UUID)r.get("id"),((Number)r.get("source_version")).longValue(),((Number)r.get("target_version")).longValue(),((Timestamp)r.get("closed_at")).toInstant(),PolicyMode.valueOf(r.get("policy_mode").toString()),(Boolean)r.get("manager_confirmed"),decode(r.get("reason")),((Number)r.get("task_count")).longValue(),new ClosureDtos.Actor(r.get("actor_role").toString(),decode(r.get("actor_display_name"))));}
 void validate(UUID order,ClosureDtos.Witness witness){try{jdbc.queryForList("SELECT logistics.validate_order_closure(?)",witness.id());var snapshots=jdbc.queryForList("SELECT snapshot::text FROM logistics.order_draft_revision WHERE order_id=? AND aggregate_version=?",order,witness.version());if(snapshots.isEmpty()||!json.readTree(snapshots.getFirst().get("snapshot").toString()).equals(json.readTree(json.writeValueAsString(orders.read(order,SCOPE,false)))))throw ClosureFailure.corrupt();}catch(org.springframework.dao.DataAccessException failure){throw ClosureFailure.corrupt();}}
 String audit(OrderReviewQueries.Source source,ClosureDtos.Witness w){if(w!=null){if(!source.lifecycleStatus().equals("CLOSED")||!source.acceptanceStatus().equals("ACCEPTED")||source.version()!=w.version())throw ClosureFailure.corrupt();validate(source.orderId(),w);return "RECORDED";}return source.lifecycleStatus().equals("CLOSED")?"LEGACY_CLOSED":"NOT_CLOSED";}
 TmsDtos.Page<ClosureDtos.Summary> page(ClosureValidation.Query q){String where=" FROM logistics.order_core c JOIN logistics.tom_order t ON t.order_id=c.id LEFT JOIN logistics.tom_order_closure w ON w.order_id=c.id WHERE c.company_scope=?";var args=new ArrayList<Object>();args.add(SCOPE);
  where+=switch(q.state()){case "OPEN"->" AND c.lifecycle_status='OPEN' AND t.acceptance_status='ACCEPTED'";case "RECORDED"->" AND w.id IS NOT NULL";case "LEGACY_CLOSED"->" AND c.lifecycle_status='CLOSED' AND w.id IS NULL";default->"";};long count=jdbc.queryForObject("SELECT count(*)"+where,Long.class,args.toArray());args.add(q.size());args.add((long)q.page()*q.size());var rows=jdbc.queryForList("SELECT c.id,c.order_no,c.lifecycle_status,c.updated_at,t.order_type,t.acceptance_status,t.version,w.closed_at,w.id AS witness_id"+where+" ORDER BY c.updated_at DESC,c.id LIMIT ? OFFSET ?",args.toArray());
  var values=new ArrayList<ClosureDtos.Summary>();for(var r:rows){UUID id=(UUID)r.get("id");var w=witness(id);if(w.isPresent())validate(id,w.get());String status=r.get("lifecycle_status").toString();values.add(new ClosureDtos.Summary(id,r.get("order_no").toString(),r.get("order_type").toString(),status,r.get("acceptance_status").toString(),((Number)r.get("version")).longValue(),w.isPresent()?"RECORDED":status.equals("CLOSED")?"LEGACY_CLOSED":"NOT_CLOSED",((Timestamp)r.get("updated_at")).toInstant(),w.isEmpty()?null:w.get().closedAt()));}return TmsDtos.Page.of(values,q.page(),q.size(),count);
 }
 boolean key(UUID actor,String path,String key){return orders.tryKeyLock(SCOPE,actor,"POST",path,key);}
 Optional<Receipt> receipt(UUID actor,String path,String key){var rows=jdbc.queryForList("SELECT request_hash,original_data::text FROM logistics.tom_order_closure_command WHERE company_scope=? AND actor_id=? AND http_method='POST' AND canonical_path=? AND idempotency_key=?",SCOPE,actor,path,key);return rows.isEmpty()?Optional.empty():Optional.of(new Receipt(rows.getFirst().get("request_hash").toString(),ManagementReceiptCodec.closure(rows.getFirst().get("original_data").toString())));}
 void close(OrderReviewQueries.Source source,Map<UUID,OrderClosureFacts.TaskFact> facts,AccountDto actor,ClosureDtos.Result result,String reason,String path,String key,String hash,String trace){var w=result.closure();var at=OffsetDateTime.ofInstant(w.closedAt(),ZoneOffset.UTC);UUID receipt=UUID.randomUUID();var full=orders.close(source.orderId(),SCOPE,actor.id(),w.closedAt(),source.version());orders.revision(source.orderId(),full,trace,actor.id(),w.closedAt());
  jdbc.update("INSERT INTO logistics.tom_order_closure(id,order_id,company_scope,source_version,target_version,lifecycle_status,acceptance_status,closed_at,actor_id,actor_role,actor_display_name,reason,policy_mode,manager_confirmed,task_count,policy_snapshot,receipt_id) VALUES (?,?,?,?,?,'CLOSED','ACCEPTED',?,?,?,?,?,'SYNTHETIC_TEST_ONLY',true,?,?::json,?)",w.id(),source.orderId(),SCOPE,source.version(),w.version(),at,actor.id(),actor.role().name(),actor.displayName().getBytes(StandardCharsets.UTF_8),reason.getBytes(StandardCharsets.UTF_8),w.taskCount(),"{\"taskBasis\":\"ALL_PERSISTED_TASKS\"}",receipt);
  for(var task:source.tasks()){var f=facts.get(task.taskId());jdbc.update("INSERT INTO logistics.tom_order_closure_task(closure_id,order_id,source_version,task_id,required_task,assignment_id,completion_id,execution_version,confirmation_id,confirmation_version) VALUES (?,?,?,?,?,?,?,?,?,1)",w.id(),source.orderId(),source.version(),task.taskId(),task.requiredTask(),f.assignmentId(),f.completionId(),f.executionVersion(),f.confirmationId());}
  jdbc.update("INSERT INTO logistics.tom_order_closure_command(id,closure_id,order_id,company_scope,actor_id,http_method,canonical_path,idempotency_key,request_hash,original_status,original_data,created_at) VALUES (?,?,?,?,?,'POST',?,?,?,200,?::json,?)",receipt,w.id(),source.orderId(),SCOPE,actor.id(),path,key,hash,ManagementReceiptCodec.closure(result),at);
 }
 TmsDtos.Page<ClosureDtos.TaskReview> recordedTasks(UUID order,ClosureDtos.Witness w,ClosureValidation.Query q){validate(order,w);var rows=jdbc.queryForList("SELECT m.*,t.task_no FROM logistics.tom_order_closure_task m JOIN logistics.transport_task t ON t.id=m.task_id WHERE m.closure_id=? ORDER BY t.task_no,t.id LIMIT ? OFFSET ?",w.id(),q.size(),(long)q.page()*q.size());var observed=facts.recorded(order,w.sourceVersion(),rows.stream().map(r->(UUID)r.get("task_id")).toList());
  return TmsDtos.Page.of(rows.stream().map(r->{var f=observed.get((UUID)r.get("task_id"));if(f==null||!f.verified()||f.confirmationVersion()!=1||!Objects.equals(f.confirmationId(),r.get("confirmation_id")))throw ClosureFailure.corrupt();return new ClosureDtos.TaskReview(order,w.sourceVersion(),(UUID)r.get("task_id"),r.get("task_no").toString(),(Boolean)r.get("required_task"),(UUID)r.get("assignment_id"),(UUID)r.get("completion_id"),ExecutionPhase.COMPLETED,((Number)r.get("execution_version")).longValue(),true,1,f.confirmedAt(),0,0);}).toList(),q.page(),q.size(),w.taskCount());}
 private static String decode(Object raw){try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap((byte[])raw)).toString();}catch(java.nio.charset.CharacterCodingException failure){throw ClosureFailure.corrupt();}}
}
